      const d2 = Math.sqrt((dx-sX2)**2+(dy-sY2)**2);
      cross += Math.sin((d*f+d2*f2)*0.3-t*(sp+sp2)*0.25+ph+ph2)*0.15;
    }
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, crs=cross/(n*(n-1)*0.5);
  const bg = (Math.sin(dx*0.035+dy*0.022+t*0.7)+Math.sin(dx*0.028-dy*0.038+t*0.95))/2
