  const feedback = Math.tanh(r1*0.6+r2*0.4+r1*r2*0.5)*0.3;
  const cell = Math.tanh((Math.sin(dx*0.14)*Math.sin(dy*0.14)+Math.sin((dx+dy)*0.09+t)*0.5+Math.sin((dx-dy)*0.07-t*0.7)*0.3)*1.4)*0.25;
